create or replace function public.queue_loyalty_campaign(p_subject text, p_body text, p_min_spend_cents int default 0, p_days int default null) returns jsonb language plpgsql security definer set search_path = public as $$ declare v_store uuid := public.current_store_id(); v_id uuid := gen_random_uuid(); v_n int := 0; v_subject text := btrim(coalesce(p_subject, '')); v_body text := btrim(coalesce(p_body, '')); begin perform public.assert_manager(); if v_store is null then raise exception 'no_store' using errcode = 'P0001'; end if; if v_subject = '' or v_body = '' then raise exception 'subject_and_body_required' using errcode = '22023'; end if; insert into public.email_campaigns (id, store_id, subject, body_text, filter, created_by) values (v_id, v_store, v_subject, v_body, jsonb_build_object('min_spend_cents', greatest(coalesce(p_min_spend_cents, 0), 0), 'days', p_days), auth.uid()); insert into public.email_outbox (store_id, customer_id, campaign_id, kind, to_email, subject, body_text) select v_store, c.id, v_id, 'campaign', c.email, v_subject, v_body from public.customers c where c.store_id = v_store and c.email is not null and c.marketing_opt_in and c.unsubscribed_at is null and (coalesce(p_min_spend_cents, 0) <= 0 or coalesce((select sum(s.price_cents) from public.ticket_extras te join public.sales s on s.ticket_id = te.ticket_id and s.store_id = v_store where te.customer_id = c.id and s.voided_at is null and s.channel in ('floor', 'website')), 0) >= p_min_spend_cents) and (p_days is null or exists (select 1 from public.ticket_extras te join public.sales s on s.ticket_id = te.ticket_id and s.store_id = v_store where te.customer_id = c.id and s.voided_at is null and s.channel in ('floor', 'website') and s.sold_at >= now() - make_interval(days => p_days))); get diagnostics v_n = row_count; update public.email_campaigns set queued_count = v_n where id = v_id; return jsonb_build_object('campaign_id', v_id, 'queued', v_n); end; $$;
create or replace function public.claim_email_outbox(p_limit int default 40) returns jsonb language plpgsql security definer set search_path = public as $$ declare v_n int := greatest(1, least(coalesce(p_limit, 40), 80)); v_rows jsonb; begin perform public.assert_service(); with picked as (select id from public.email_outbox where status = 'queued' order by created_at limit v_n for update skip locked), marked as (update public.email_outbox o set status = 'sending' from picked where o.id = picked.id returning o.id, o.store_id, o.customer_id, o.campaign_id, o.kind, o.to_email, o.subject, o.body_text, o.payload) select coalesce(jsonb_agg(jsonb_build_object('id', m.id, 'store_id', m.store_id, 'customer_id', m.customer_id, 'campaign_id', m.campaign_id, 'kind', m.kind, 'to_email', m.to_email, 'subject', m.subject, 'body_text', m.body_text, 'payload', m.payload, 'name', c.name, 'signup_code', c.signup_code, 'unsub_token', c.unsub_token, 'points', public.customer_points_balance_internal(m.store_id, m.customer_id), 'credit_cents', public.customer_credit_cents(m.store_id, public.customer_points_balance_internal(m.store_id, m.customer_id)))), '[]'::jsonb) into v_rows from marked m left join public.customers c on c.id = m.customer_id; return coalesce(v_rows, '[]'::jsonb); end; $$;
create or replace function public.finish_email_outbox(p_id bigint, p_ok boolean, p_error text default null) returns void language plpgsql security definer set search_path = public as $$ begin perform public.assert_service(); if p_ok then update public.email_outbox set status = 'sent', sent_at = now(), error = null where id = p_id; else update public.email_outbox set status = 'error', error = left(coalesce(p_error, 'send_failed'), 500) where id = p_id; end if; end; $$;;
